CREATE TABLE "kit_templates_new" (
  "template_id" TEXT,
  "name" TEXT NOT NULL,
  "remote_agent_id" TEXT NOT NULL,
  "remote_agent_name" TEXT NOT NULL,
  "config_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "version" INTEGER NOT NULL DEFAULT 1,
  "updated_at" TEXT NOT NULL DEFAULT '',
  "deleted_at" TEXT,
  PRIMARY KEY ("template_id"),
  CHECK (version > 0)
);
INSERT INTO "kit_templates_new" ("template_id", "name", "remote_agent_id", "remote_agent_name", "config_json", "created_at", "version", "updated_at", "deleted_at") SELECT "template_id", "name", "remote_agent_id", "remote_agent_name", "config_json", "created_at", "version", "updated_at", "deleted_at" FROM "kit_templates";
DROP TABLE "kit_templates";
ALTER TABLE "kit_templates_new" RENAME TO "kit_templates";
CREATE INDEX "idx_templates_created" ON "kit_templates" ("created_at", "template_id");
CREATE UNIQUE INDEX "idx_kit_templates_name_active" ON "kit_templates" ("name") WHERE deleted_at IS NULL;
